tabs.content:
// 1. Executive Operations Overview
get_facility_operational_overview(window_minutes = 30)
| project facility_name, region, facility_health_score, health_status, total_power_consumption_kw, active_critical_alerts
| order by facility_health_score desc;

// 2. Maintenance Equipment Degradation Risk Heatmap
get_equipment_critical_anomalies(window_minutes = 30)
| project facility_id, equipment_type, critical_failure_count, equipment_health_score, failure_probability_score, equipment_risk_score
| order by equipment_risk_score desc;

// 3. Agronomy Crop Biological Stress Distribution
get_crop_biological_stress_overview(window_minutes = 30)
| project facility_id, zone_id, crop_type, crop_health_score, daily_growth_rate, biological_stress_index, high_crop_stress_count
| order by biological_stress_index desc;

// 4. Irrigation Hydraulic Flow & Pressure Audit
get_irrigation_hydraulic_anomalies(window_minutes = 30)
| project facility_id, zone_id, anomalous_cycle_count, irrigation_flow_rate_lpm, pump_pressure_kpa
| order by anomalous_cycle_count desc;

// 5. Photobiology DLI Light Deficit Audit
get_lighting_dli_deficit(window_minutes = 30)
| project facility_id, zone_id, photoperiod_deficit_count, daily_light_integral_dli, light_intensity_percentage
| order by photoperiod_deficit_count desc;

// 6. Maintenance Work Order SLA Resolution
get_maintenance_sla_breach(window_minutes = 30)
| project facility_id, equipment_id, maintenance_type, emergency_order_count, pending_order_count, avg_work_order_resolution_minutes
| order by emergency_order_count desc;

// 1. Multi-Stream Ingestion SLA & Processing Lag
get_stream_ingestion_sla(window_minutes = 30)
| project stream_name, total_ingested_events, avg_processing_lag_sec, max_processing_lag_sec, sla_breach_count, sla_breach_alert;

// 2. Dead-Letter Ingestion Anomaly Queue Rate
get_dead_letter_anomaly_rate(window_minutes = 30)
| project event_type, dead_letter_count, alert_required
| order by dead_letter_count desc;

// 3. Multi-Stream Ingress Data Quality & Schema Integrity Audit
get_ingress_data_quality_audit(window_minutes = 30)
| project total_rows, valid_schema_rows, orphan_burst_count, null_facility_count, null_timestamp_count, data_quality_score, dq_violation_alert;
